import { ethers } from '../app/contracts.js';
import { get, subscribe } from '../app/store.js';
import { openPanelPopup, closePanelPopup } from '../app/panel-popups.js';
import { formatSdgnrsRedemptionAmount } from '../app/sdgnrs.js';
import { readPurchaseInfo } from '../app/purchase-info.js';
import { displayEth, trimDisplayZeros } from '../app/scaling.js';
import { readGnrusRedemption, redeemGnrus, gnrusRedemptionValue, MIN_GNRUS_REDEEM } from '../app/gnrus.js';

let current = null;
const eth = value => trimDisplayZeros(displayEth(value, 6));
export function openGnrusDialog({ mode = 'donate', owner, trigger } = {}) {
  if (current?.busy) return;
  closePanelPopup('gnrus');
  current?.panel.remove();
  const panel = document.createElement('section');
  const redeem = mode === 'redeem';
  panel.className = 'panel-popup secondary-popup gnrus-dialog';
  panel.dataset.panelPopup = 'gnrus';
  panel.hidden = true;
  panel.setAttribute('role', 'dialog');
  panel.setAttribute('aria-modal', 'true');
  panel.setAttribute('aria-labelledby', 'gnrus-dialog-title');
  panel.innerHTML = `
    <div class="panel-popup__window">
      <header class="panel-popup__header">
        <img src="/shared/gnrus-logo.svg" width="44" height="44" alt="">
        <h2 id="gnrus-dialog-title">${redeem ? 'REDEEM GNRUS' : 'DONATE TO GNRUS'}</h2>
        <button type="button" class="panel-popup__close" data-panel-close aria-label="Close GNRUS">×</button>
      </header>
      <div class="panel-popup__body">
        ${redeem ? '<p class="gnrus-dialog__balance" data-balance>Loading balance…</p>' : `
          <div class="gnrus-dialog__choices" role="group" aria-label="Donation type">
            <button type="button" data-kind="tickets" aria-pressed="true">TICKETS · ETH</button>
            <button type="button" data-kind="flip" aria-pressed="false">FLIP</button>
          </div>`}
        <label class="gnrus-dialog__label" for="gnrus-amount">${redeem ? 'GNRUS TO REDEEM' : 'TICKETS'}</label>
        <div class="gnrus-dialog__input-row">
          <input id="gnrus-amount" type="text" inputmode="decimal" autocomplete="off" value="${redeem ? '' : '1'}" aria-describedby="gnrus-quote">
          ${redeem ? '<button type="button" data-min disabled>MIN</button><button type="button" data-max disabled>MAX</button>' : ''}
        </div>
        <p class="gnrus-dialog__quote" id="gnrus-quote" data-quote aria-live="polite">Loading…</p>
        ${redeem ? '' : '<p class="gnrus-dialog__notice">Donations will open with the next contract update.</p>'}
        <p class="gnrus-dialog__feedback" data-feedback role="status" hidden></p>
        <button type="button" class="gnrus-dialog__submit" data-submit disabled>${redeem ? 'REDEEM' : 'DONATE'}</button>
      </div>
    </div>`;
  document.body.append(panel);
  const state = current = { panel, busy: false, kind: 'tickets', quote: null, redemption: null, closed: false };
  const input = panel.querySelector('input');
  const submit = panel.querySelector('[data-submit]');
  const feedback = panel.querySelector('[data-feedback]');
  const owns = () => get('ui.mode') === 'self' && String(get('connected.address') || '').toLowerCase() === owner;
  const amount = () => {
    try {
      if (!/^\d+(?:\.\d{0,18})?$/.test(input.value.trim())) return null;
      return ethers.parseEther(input.value.trim());
    } catch { return null; }
  };
  const paint = () => {
    if (state.closed) return;
    const value = amount();
    let quote = 'Enter an amount.';
    if (redeem) {
      if (!state.redemption) quote = 'Loading redemption value…';
      else if (value != null && value >= MIN_GNRUS_REDEEM && value <= state.redemption.balance) {
        quote = `≈${eth(gnrusRedemptionValue(state.redemption, value))} ETH`;
      } else if (value != null && value > state.redemption.balance) quote = 'Not enough GNRUS.';
      else quote = 'Minimum 1 GNRUS.';
      submit.disabled = state.busy || !owns() || !state.redemption || value == null
        || value < MIN_GNRUS_REDEEM || value > state.redemption.balance;
    } else {
      if (state.kind === 'flip') quote = value > 0n && value % MIN_GNRUS_REDEEM === 0n
        ? `${(value / MIN_GNRUS_REDEEM).toLocaleString('en-US')} FLIP` : 'Enter a whole FLIP amount.';
      else if (state.quote?.priceWei > 0n) quote = value > 0n && value % MIN_GNRUS_REDEEM === 0n
        ? `${eth(state.quote.priceWei * (value / MIN_GNRUS_REDEEM))} ETH` : 'Enter a whole ticket amount.';
      else quote = 'Ticket price unavailable.';
      // No write is exposed until deployed contracts have a supported donation entry point.
      submit.disabled = true;
    }
    panel.querySelector('[data-quote]').textContent = quote;
    submit.textContent = state.busy ? 'REDEEMING…' : redeem ? 'REDEEM' : 'DONATE';
  };
  const unsubs = ['connected.address', 'viewing.address', 'ui.mode'].map(key => subscribe(key, () => {
    if (!owns()) closePanelPopup('gnrus');
  }));
  panel.addEventListener('app:panel-close', () => { state.closed = true; unsubs.forEach(unsub => unsub()); }, { once: true });
  input.addEventListener('input', paint);
  panel.querySelectorAll('[data-kind]').forEach(button => button.addEventListener('click', () => {
    state.kind = button.dataset.kind;
    panel.querySelectorAll('[data-kind]').forEach(choice => choice.setAttribute('aria-pressed', String(choice === button)));
    panel.querySelector('label').textContent = state.kind === 'tickets' ? 'TICKETS' : 'FLIP';
    input.value = state.kind === 'tickets' ? '1' : '1000';
    paint();
  }));
  panel.querySelector('[data-min]')?.addEventListener('click', () => { input.value = '1'; paint(); });
  panel.querySelector('[data-max]')?.addEventListener('click', () => {
    input.value = ethers.formatEther(state.redemption.balance); paint();
  });
  submit.addEventListener('click', async () => {
    if (!redeem || submit.disabled || state.busy || !owns()) return;
    const value = amount();
    state.busy = true;
    input.disabled = true;
    panel.querySelectorAll('[data-min], [data-max]').forEach(button => { button.disabled = true; });
    feedback.hidden = true;
    paint();
    try {
      await redeemGnrus({ amount: value, expectedAccount: owner });
      if (!state.closed) closePanelPopup('gnrus');
    } catch (error) {
      if (!state.closed) { feedback.textContent = error.userMessage || error.message || 'Redemption failed. Try again.'; feedback.hidden = false; }
    } finally {
      state.busy = false;
      input.disabled = false;
      panel.querySelectorAll('[data-min], [data-max]').forEach(button => { button.disabled = !state.redemption; });
      paint();
    }
  });
  openPanelPopup('gnrus', trigger, panel);
  paint();
  void (async () => {
    try {
      if (redeem) {
        const result = await readGnrusRedemption(owner);
        if (state.closed) return;
        state.redemption = result;
        input.value = ethers.formatEther(result.balance);
        panel.querySelector('[data-balance]').textContent = `${formatSdgnrsRedemptionAmount(result.balance)} GNRUS available`;
        panel.querySelectorAll('[data-min], [data-max]').forEach(button => { button.disabled = result.balance < MIN_GNRUS_REDEEM; });
      } else state.quote = await readPurchaseInfo({ fresh: true });
      paint();
    } catch (error) {
      if (!state.closed) { feedback.textContent = error.userMessage || 'Could not load the latest balance or price. Reopen to retry.'; feedback.hidden = false; }
    }
  })();
}
